<https://example.org/openevidence/questions/q_hyperlipidemia_efficacy> a holon:ClinicalQuestionHolon ;
    oe:questionText "How effective is atorvastatin compared with other agents for Hyperlipidemia?"^^xsd:string ;
    oe:answerText "Patients with severe hypertriglyceridemia have an increased risk of acute pancreatitis. The efficacy and safety of olezarsen, an antisense oligonucleotide targeting apolipoprotein C-III messenger RNA, have not been established in this population."^^xsd:string ;
    holon:hasInteriorGraph <https://example.org/openevidence/questions/q_hyperlipidemia_efficacy-int> ;
    holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_hyperlipidemia_efficacy-bou> ;
    holon:hasProjectionGraph <https://example.org/openevidence/questions/q_hyperlipidemia_efficacy-pro> ;
    holon:hasContextGraph <https://example.org/openevidence/questions/q_hyperlipidemia_efficacy-con> .

<https://example.org/openevidence/drugs/atorvastatin> oe:treats <https://example.org/openevidence/diseases/hyperlipidemia> .
<https://example.org/openevidence/generated/ev_q_hyperlipidemia_efficacy_0> a holon:EvidenceAssertion ;
    rdf:reifies <https://example.org/openevidence/generated/ev_q_hyperlipidemia_efficacy_0-tt> ;
    holon:confidence "0.87"^^xsd:decimal ;
    holon:evidenceLevel "Level-1B" ;
    holon:assessedBy <https://example.org/openevidence/questions/openevidence_ai> ;
    holon:recordedOn "2026-12-31"^^xsd:date ;
    oe:cites <https://example.org/openevidence/sources/41211918> ;
    holon:inHolon <https://example.org/openevidence/questions/q_hyperlipidemia_efficacy> ;
    oe:effectiveness "effective" .
<https://example.org/openevidence/generated/ev_q_hyperlipidemia_efficacy_0-tt> rdf:subject <https://example.org/openevidence/drugs/atorvastatin> ;
    rdf:predicate oe:treats ;
    rdf:object <https://example.org/openevidence/diseases/hyperlipidemia> .

<https://example.org/openevidence/drugs/levothyroxine> oe:treats <https://example.org/openevidence/diseases/hypothyroidism> .   # ungrounded (naive)
